import 'package:mad_flutter_practicum/domain/domain.dart';

class HomePage extends StatefulWidget {
  const HomePage({super.key});

  @override
  State<HomePage> createState() => _HomePageState();
}

class _HomePageState extends State<HomePage> {
  int _selectedIndex = 0;

  final GlobalKey<CurrencyListPageState> _currencyListKey = GlobalKey<CurrencyListPageState>();
  final GlobalKey<NewsListPageState> _newsListKey = GlobalKey<NewsListPageState>();

  static const List<Widget> _pages = <Widget>[
    CurrencyListPage(),
    NewsListPage(),
    ProfilePage(),
  ];

  void _onItemTapped(int index) {
    setState(() {
      _selectedIndex = index;
    });
  }

  Future<void> _refreshAll() async {
    final List<Future<void>> futures = <Future<void>>[];

    if (_selectedIndex == 0 && _currencyListKey.currentState != null) {
      futures.add(_currencyListKey.currentState!.refresh());
    } else {
      futures.add(_currencyListKey.currentState?.refresh() ?? Future.value());
    }

    if (_selectedIndex == 1 && _newsListKey.currentState != null) {
      futures.add(_newsListKey.currentState!.refresh());
    } else {
      futures.add(_newsListKey.currentState?.refresh() ?? Future.value());
    }

    await Future.wait(futures);
  }

  @override
  Widget build(BuildContext context) {
    final Widget currentPage = _pages[_selectedIndex];
    final AppLocalizations loc = context.loc;

    return Scaffold(
      appBar: AppBar(
        title: Text(loc.currencyRate),
        actions: <Widget>[
          IconButton(
            icon: const Icon(Icons.refresh),
            tooltip: loc.refreshAll,
            onPressed: _refreshAll,
          ),
        ],
      ),
      body: IndexedStack(
        index: _selectedIndex,
        children: <Widget>[
          CurrencyListPage(key: _currencyListKey),
          NewsListPage(key: _newsListKey),
          ProfilePage(),
        ],
      ),
      bottomNavigationBar: Container(
        decoration: BoxDecoration(
          boxShadow: <BoxShadow>[
            BoxShadow(
              color: context.colors.bottomNavBarShadow,
              blurRadius: 25,
              offset: Offset(0.0, 0.75),
            ),
          ],
        ),
        child: BottomNavigationBar(
          currentIndex: _selectedIndex,
          onTap: _onItemTapped,
          items: <BottomNavigationBarItem>[
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/home.png',
                isSelected: currentPage is CurrencyListPage,
              ),
              label: loc.currencyRate,
            ),
            BottomNavigationBarItem(
              icon: TabWidget(
                assetPath: 'assets/icons/news.png',
                isSelected: currentPage is NewsListPage,
              ),
              label: loc.news,
            ),
            const BottomNavigationBarItem(
              icon: Icon(Icons.person),
              label: 'profile',
            ),
          ],
        ),
      ),
    );
  }
}

class TabWidget extends StatelessWidget {
  const TabWidget({
    super.key,
    required this.assetPath,
    required this.isSelected,
  });

  final String assetPath;
  final bool isSelected;

  @override
  Widget build(BuildContext context) {
    final ThemeColors colors = context.colors;

    return SizedBox.square(
      dimension: 24,
      child: Image.asset(
        assetPath,
        color: isSelected ? colors.bottomNavBarSelectedItem : colors.bottomNavBarUnselectedItem,
      ),
    );
  }
}
